@startuml

class User {
  + fullName : string
}

class UnderAged extends User {
  + studentCard : string
}

class Adult extends User {
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowHistory {
  + date : date
}

User "1" -- "0..4" Book : borrows
User "1" *-- "0..*" BorrowHistory : has
BorrowHistory "0..*" -- "1" Book : refers to

@enduml

